{"path": "media.py", "content": """"Immutable media inventory and sampled, explicitly limited visual evidence."""
import base64
import hashlib
import json
import subprocess
from pathlib import Path
from agent_core import sha256_file

EXT = {'.mp4': 'video', '.mov': 'video', '.mkv': 'video', '.webm': 'video', '.avi': 'video', '.png': 'image', '.jpg': 'image', '.jpeg': 'image', '.webp': 'image', '.wav': 'audio', '.mp3': 'audio', '.m4a': 'audio', '.flac': 'audio'}


def command(argv, timeout=180):
    p = subprocess.run(argv, capture_output=True, text=True, timeout=timeout)
    if p.returncode:
        raise RuntimeError(f'{argv[0]} exit {p.returncode}: {p.stderr[-3000:]}')
    return p.stdout


def probe(path, config):
    return json.loads(command([config.ffprobe, '-v', 'error', '-show_streams', '-show_format', '-of', 'json', str(path)]))


def inventory(root, config):
    root = Path(root).resolve()
    assets = []
    for p in sorted(root.rglob('*')):
        if not p.is_file() or p.suffix.lower() not in EXT:
            continue
        info = probe(p, config)
        streams = info.get('streams', [])
        video = next((s for s in streams if s['codec_type'] == 'video'), None)
        audio = next((s for s in streams if s['codec_type'] == 'audio'), None)
        kind = EXT[p.suffix.lower()]
        if kind == 'video' and not video:
            raise ValueError(f'Video input has no video stream: {p}')
        if kind == 'audio' and not audio:
            raise ValueError(f'Audio input has no audio stream: {p}')
        sha = sha256_file(p)
        fps = video.get('avg_frame_rate', '0/0') if video else None
        rel = p.relative_to(root).as_posix()
        duration = info.get('format', {}).get('duration')
        assets.append({'asset_id': hashlib.sha256((rel + ':' + sha).encode()).hexdigest()[:16], 'relative_path': rel,
                       'sha256': sha, 'kind': kind, 'duration_ms': round(float(duration) * 1000) if duration and kind != 'image' else None,
                       'width': video.get('width') if kind != 'audio' else None, 'height': video.get('height') if kind != 'audio' else None,
                       'fps': fps if kind == 'video' else None, 'rotation': next((int(x.get('rotation', 0)) for x in video.get('side_data_list', []) if 'rotation' in x), 0) if video else 0,
                       'has_audio': bool(audio), 'probe_summary': {'format_name': info.get('format', {}).get('format_name'), 'streams': [{k: s.get(k) for k in ('codec_type', 'codec_name', 'duration', 'sample_rate', 'channel_layout')} for s in streams]}})
    if not assets:
        raise ValueError('No media found')
    manifest_hash = hashlib.sha256(json.dumps([(a['relative_path'], a['sha256']) for a in assets], sort_keys=True).encode()).hexdigest()
    return {'asset_root': str(root), 'assets': assets, 'manifest_hash': manifest_hash}


def frames(asset, root, run_dir, config, points, prefix):
    p = Path(root) / asset['relative_path']
    target = Path(run_dir) / 'frames'
    target.mkdir(exist_ok=True)
    results = []
    for ms in points:
        name = f"{prefix}_{asset['asset_id']}_{ms}.jpg"
        dest = target / name
        if not dest.exists():
            argv = [config.ffmpeg, '-hide_banner', '-loglevel', 'error', '-threads', '1', '-y']
            if asset['kind'] == 'video':
                argv += ['-ss', f'{ms / 1000:.3f}']
            argv += ['-i', str(p), '-frames:v', '1', '-vf', 'scale=640:-2', '-q:v', '3', str(dest)]
            command(argv)
        results.append({'time_ms': ms, 'path': str(dest.resolve()), 'sha256': sha256_file(dest)})
    return results


def observe(asset, inventory_data, run_dir, config, model, points=None, prefix='sample'):
    if asset['kind'] == 'audio':
        return {'asset_id': asset['asset_id'], 'summary': 'Audio only; probe metadata, no visual evidence or semantic transcription.', 'observed_intervals': [], 'candidate_shots': [], 'evidence_frames': [], 'uncertainties': ['Audio semantics not transcribed']}
    if points is None:
        duration = asset['duration_ms'] or 0
        points = [0, 2500, 5000, 7500, max(0, duration - 200)] if asset['kind'] == 'video' else [0]
        points = sorted(set(t for t in points if t < duration)) if asset['kind'] == 'video' else [0]
    samples = frames(asset, inventory_data['asset_root'], run_dir, config, points, prefix)
    content = [{'type': 'input_text', 'text': f"Describe only what is actually visible in these sampled frames of {asset['relative_path']}; each frame is a point observation, not proof of intervening scenes. Return a short factual description, possible shot choices, and uncertainty."}]
    for frame in samples:
        content += [{'type': 'input_text', 'text': f"Observed timestamp {frame['time_ms']} ms, evidence {frame['path']}"}, {'type': 'input_image', 'image_url': 'data:image/jpeg;base64,' + base64.b64encode(Path(frame['path']).read_bytes()).decode()}]
    response = model.respond([{'role': 'user', 'content': content}], purpose='visual_asset_analysis')
    summary = response.output_text.strip()
    return {'asset_id': asset['asset_id'], 'summary': summary, 'observed_intervals': [{'start_ms': f['time_ms'], 'end_ms': f['time_ms'], 'description': 'Sampled point; see summary'} for f in samples], 'candidate_shots': [{'start_ms': 0, 'end_ms': min(asset['duration_ms'], 7000), 'status': 'candidate, intervening content unobserved'}] if asset['kind'] == 'video' else [{'status': 'static image'}], 'evidence_frames': samples, 'uncertainties': ['Content between sampled frames is not verified'] if asset['kind'] == 'video' else []}
"}

{"path": "timeline.py", "content": """"Strict editable timeline schema and source/constraint semantic checks."""
from typing import Literal
from pydantic import BaseModel, ConfigDict, Field, StrictInt, field_validator


class Strict(BaseModel):
    model_config = ConfigDict(extra='forbid')


class Output(Strict):
    width: StrictInt = Field(gt=0)
    height: StrictInt = Field(gt=0)
    fps: StrictInt = Field(gt=0)
    container: Literal['mp4']
    video_codec: Literal['libx264']
    audio_codec: Literal['aac']


class Transition(Strict):
    type: Literal['cut', 'fade', 'dissolve']
    duration_ms: StrictInt = Field(ge=0)


class Clip(Strict):
    clip_id: str
    asset_id: str
    kind: Literal['video', 'image']
    in_ms: StrictInt | None
    out_ms: StrictInt | None
    duration_ms: StrictInt | None
    fit: Literal['pad', 'crop']
    mute: bool
    gain_db: float
    transition_out: Transition


class Caption(Strict):
    caption_id: str
    start_ms: StrictInt = Field(ge=0)
    end_ms: StrictInt = Field(ge=0)
    text: str
    style_id: Literal['default_zh']


class BGM(Strict):
    asset_id: str
    in_ms: StrictInt = Field(ge=0)
    start_ms: StrictInt = Field(ge=0)
    gain_db: float
    loop: bool
    fade_in_ms: StrictInt = Field(ge=0)
    fade_out_ms: StrictInt = Field(ge=0)


class Timeline(Strict):
    schema_version: Literal['1.0']
    version: StrictInt = Field(gt=0)
    parent_version: StrictInt | None
    request_ids: list[str]
    asset_manifest_hash: str
    constraint_set_id: str
    output: Output
    clips: list[Clip]
    captions: list[Caption]
    bgm: BGM | None


def check(data, inventory, requirements):
    t = Timeline.model_validate(data)
    assets = {a['asset_id']: a for a in inventory['assets']}
    if t.asset_manifest_hash != inventory['manifest_hash'] or t.constraint_set_id != requirements['constraint_set_id']:
        raise ValueError('Asset/constraint hash mismatch')
    if t.version != requirements['version'] or t.parent_version != (t.version - 1 if t.version > 1 else None):
        raise ValueError('Incorrect revision lineage')
    if t.request_ids != requirements['request_ids']:
        raise ValueError('Request lineage mismatch')
    if not t.clips or len({c.clip_id for c in t.clips}) != len(t.clips) or len({c.caption_id for c in t.captions}) != len(t.captions):
        raise ValueError('Missing clips or duplicate IDs')
    positions, elapsed, prev_overlap = [], 0, 0
    for i, c in enumerate(t.clips):
        a = assets.get(c.asset_id)
        if a is None or a['kind'] != c.kind:
            raise ValueError(f'{c.clip_id}: invalid video/image asset')
        if c.kind == 'video':
            if c.in_ms is None or c.out_ms is None or c.duration_ms is not None or c.in_ms < 0 or c.out_ms <= c.in_ms or c.out_ms > a['duration_ms']:
                raise ValueError(f'{c.clip_id}: video source interval invalid')
            length = c.out_ms - c.in_ms
        else:
            if c.in_ms is not None or c.out_ms is not None or c.duration_ms is None or c.duration_ms <= 0:
                raise ValueError(f'{c.clip_id}: image duration/source invalid')
            length = c.duration_ms
        tr = c.transition_out
        if (tr.type == 'cut' and tr.duration_ms != 0) or (tr.type != 'cut' and (tr.duration_ms <= 0 or tr.duration_ms >= length)):
            raise ValueError(f'{c.clip_id}: transition duration invalid')
        if i == len(t.clips) - 1 and tr.type == 'dissolve':
            raise ValueError('Last clip cannot dissolve')
        if prev_overlap + (tr.duration_ms if tr.type == 'dissolve' else 0) > length:
            raise ValueError('Neighboring dissolve overlaps exceed clip length')
        start = elapsed - prev_overlap
        positions.append({'clip_id': c.clip_id, 'start_ms': start, 'end_ms': start + length})
        elapsed = start + length
        prev_overlap = tr.duration_ms if tr.type == 'dissolve' else 0
    for c in t.captions:
        if not c.text or c.end_ms <= c.start_ms or c.end_ms > elapsed:
            raise ValueError(f'{c.caption_id}: caption outside movie')
    if t.bgm:
        a = assets.get(t.bgm.asset_id)
        if not a or a['kind'] != 'audio' or t.bgm.start_ms >= elapsed or t.bgm.in_ms >= a['duration_ms'] or (not t.bgm.loop and elapsed - t.bgm.start_ms > a['duration_ms'] - t.bgm.in_ms) or t.bgm.fade_in_ms + t.bgm.fade_out_ms > elapsed - t.bgm.start_ms:
            raise ValueError('BGM source/range/fades invalid')
    actual = {'duration_ms': elapsed, 'width': t.output.width, 'height': t.output.height, 'fps': t.output.fps, 'container': t.output.container, 'video_codec': t.output.video_codec, 'audio_codec': t.output.audio_codec,
              'clip_order': [c.kind for c in t.clips], 'title_text': next((c.text for c in t.captions if c.start_ms == 0), None), 'title_start_ms': 0, 'title_end_ms': next((c.end_ms for c in t.captions if c.start_ms == 0), None),
              'ending_text': next((c.text for c in t.captions if c.end_ms == elapsed), None), 'ending_start_ms': next((c.start_ms for c in t.captions if c.end_ms == elapsed), None), 'ending_end_ms': elapsed,
              'transition_type': t.clips[0].transition_out.type, 'transition_ms': t.clips[0].transition_out.duration_ms,
              'video_gain_db': [c.gain_db for c in t.clips if c.kind == 'video'], 'video_mute': [c.mute for c in t.clips if c.kind == 'video'],
              'bgm_gain_db': t.bgm.gain_db if t.bgm else None, 'bgm_fade_in_ms': t.bgm.fade_in_ms if t.bgm else None, 'bgm_fade_out_ms': t.bgm.fade_out_ms if t.bgm else None,
              'fit': [c.fit for c in t.clips]}
    failures = []
    for req in requirements['hard_constraints']:
        key, expected = req['field'], req['expected']
        got = actual.get(key)
        if key in ('video_gain_db', 'video_mute', 'fit'):
            good = bool(got) and all(x == expected for x in got)
        elif key == 'clip_order':
            good = got == expected
        else:
            good = got == expected
        if not good:
            failures.append({'requirement_id': req['requirement_id'], 'field': key, 'expected': expected, 'actual': got})
    if failures:
        raise ValueError(f'Hard constraint violations: {failures}')
    return t, {'computed_duration_ms': elapsed, 'clip_positions': positions, 'constraint_checks': [{'requirement_id': x['requirement_id'], 'field': x['field'], 'actual': actual[x['field']], 'status': 'pass'} for x in requirements['hard_constraints']]}
"}

