from __future__ import annotations
import argparse
import hashlib
import json
import os
from pathlib import Path
import sys
import time
from pydantic import BaseModel, ConfigDict, StrictInt, Field
from agent_core import AgentLoop, EventLogger, ModelClient, load_config, sha256_file
import media
